select * from bus_sales s join bus_customer c on s.customerid=c.id join bus_goods g on s.goodsid=g.id
	
		
		   and s.customerid =#{customerid}
		   
		   
		   and s.goodsid =#{goodsid}
		  
		  
		   and s.orderid =#{orderid}
		  
		  
		   and s.salestime >= #{startTime}
		  
	      
	       and s.salestime <= DATE_ADD(#{endTime}, INTERVAL 1 DAY)
	      
	
	limit #{index},#{limit}

 		select count(*) from bus_sales s join bus_customer c on s.customerid=c.id join bus_goods g on s.goodsid=g.id
			
				
				   and s.customerid =#{customerid}
				   
				   
				   and s.goodsid =#{goodsid}
				  
				   
				   and s.orderid =#{orderid}
				  
				  
				   and s.salestime >= #{startTime}
				  
			      
			       and s.salestime <= DATE_ADD(#{endTime}, INTERVAL 1 DAY)
